import{_ as t,o,c as a,a7 as r}from"./chunks/framework.DUCm5Bu5.js";const g=JSON.parse('{"title":"Troubleshooting","description":"Diagnose build, configuration, startup, network, persistence and SDK failures in order.","frontmatter":{"title":"Troubleshooting","description":"Diagnose build, configuration, startup, network, persistence and SDK failures in order.","updated":"2026-10-18T00:00:00.000Z"},"headers":[],"relativePath":"en/guides/troubleshooting.md","filePath":"en/guides/troubleshooting.md"}'),n={name:"en/guides/troubleshooting.md"};function i(s,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h2 id="what-this-page-covers" tabindex="-1">What this page covers <a class="header-anchor" href="#what-this-page-covers" aria-label="Permalink to &quot;What this page covers&quot;">​</a></h2><p>This page turns &quot;the server does not work&quot; into an ordered investigation: what to check first, where the evidence lives, and which change fixes the problem. Each symptom follows one shape: symptom, check, likely cause, fix, confirm recovery. It covers a source checkout and a release directory; it does not replace a test with a real game client.</p><p><strong>Who this is for.</strong> Operators starting a server for the first time, and contributors whose build or validation gate fails.</p><p><strong>Before you start.</strong></p><ul><li>Work from the repository root for a source checkout, or from the release directory for a published build.</li><li>For local checks, copy <code>.env.example</code> to the git-ignored <code>.env</code> and set <code>BFF_MYSQL_PASSWORD</code> to a nonempty disposable value. Profile interpolation requires it even when MySQL is disabled.</li><li>Every local Host command on this page includes <code>--patch tools/local-checks/isolated-memory.patch.yaml</code>. The patch disables <code>persistence.mysql</code> and enables <code>persistence.memory</code>, so a developer <code>.env</code> or local patch cannot point the server at a live database.</li><li>Read the first error, change one thing per attempt, and keep the failing output.</li></ul><h2 id="first-checks" tabindex="-1">First checks <a class="header-anchor" href="#first-checks" aria-label="Permalink to &quot;First checks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>First check</th><th>Likely area</th><th>Section</th></tr></thead><tbody><tr><td>Build does not finish</td><td>rerun with <code>dotnet build BubbleFighter.Fantasy.sln -c Release</code>; read the first error</td><td>toolchain, restore, warnings-as-errors</td><td>Toolchain and build</td></tr><tr><td><code>error:</code> names an environment variable or profile</td><td><code>--dump-config</code> with the isolated patch</td><td>profile, patch, <code>.env</code> interpolation</td><td>Configuration</td></tr><tr><td><code>error: Server startup did not converge</code></td><td>read every listed row id and state</td><td>activation, dependencies, client data</td><td>Startup and activation</td></tr><tr><td>A row stays <code>Pending</code></td><td><code>/api/plugins</code>; read <code>state</code> and <code>error</code></td><td>missing service, provider or definition source</td><td>Startup and activation</td></tr><tr><td>A row is <code>Failed</code>, <code>CleanupIncomplete</code> or <code>CleanupFailed</code></td><td>same JSON, then the console log</td><td>activation or teardown ownership</td><td>Startup and activation</td></tr><tr><td>Client cannot connect</td><td>listening port and advertised address</td><td>bind, NAT, firewall, relay</td><td>Ports and network</td></tr><tr><td>Admin API or WebUI unreachable or 401</td><td><code>/health</code>, <code>BFF_ADMIN_HOST</code>, <code>BFF_ADMIN_TOKEN</code></td><td>admin listener and authentication</td><td>Ports and network</td></tr><tr><td>Database error, or data gone after restart</td><td><code>--dump-config</code>; persistence rows</td><td>MySQL, SQLite, migrations, memory</td><td>Persistence</td></tr><tr><td><code>clientdata</code> activation failure</td><td>the two paths in the error</td><td>client-data files and <code>BFF_CLIENT_DATA</code></td><td>Client data</td></tr><tr><td>SDK plugin fails or times out</td><td>plugin stderr and loader row config</td><td>JSON-RPC stdout, protocol, limits</td><td>SDK plugins</td></tr></tbody></table><p>If nothing matches, go to <a href="#reporting-a-problem">Reporting a problem</a>.</p><h2 id="toolchain-and-build-problems" tabindex="-1">Toolchain and build problems <a class="header-anchor" href="#toolchain-and-build-problems" aria-label="Permalink to &quot;Toolchain and build problems&quot;">​</a></h2><h3 id="the-net-sdk-is-missing-or-not-version-10" tabindex="-1">The .NET SDK is missing or not version 10 <a class="header-anchor" href="#the-net-sdk-is-missing-or-not-version-10" aria-label="Permalink to &quot;The .NET SDK is missing or not version 10&quot;">​</a></h3><p><strong>Symptom.</strong> <code>dotnet</code> is not found, or the build rejects the <code>net10.0</code> target. <strong>Check.</strong> Run <code>dotnet --info</code>; it lists installed SDKs and runtimes, and every project targets <code>net10.0</code>. <strong>Likely cause.</strong> No .NET 10 SDK, or <code>PATH</code> still points at an older one. <strong>Fix.</strong> Install the .NET 10 SDK and open a new terminal. <strong>Confirm recovery.</strong> <code>dotnet --version</code> reports 10.x and <code>dotnet build BubbleFighter.Fantasy.sln -c Release</code> ends with <code>0 Warning(s)</code> and <code>0 Error(s)</code>.</p><h3 id="package-restore-or-compilation-fails" tabindex="-1">Package restore or compilation fails <a class="header-anchor" href="#package-restore-or-compilation-fails" aria-label="Permalink to &quot;Package restore or compilation fails&quot;">​</a></h3><p><strong>Symptom.</strong> The build stops during NuGet restore with a network or feed error, or the compiler reports a warning and fails. <strong>Check.</strong> Read the first restore error; then check whether the message is a compiler warning. <code>TreatWarningsAsErrors</code> is on for every project and <code>GenerateDocumentationFile</code> requires a real XML summary on every public type and member. <strong>Likely cause.</strong> No access to the package feed, a proxy, a corrupted package cache, a missing XML comment, an unused variable or a nullability mistake. <strong>Fix.</strong> Restore again with <code>dotnet restore</code>, fix network or proxy settings, and fix the warning&#39;s cause — never suppress the warning to get a green build. <strong>Confirm recovery.</strong> The build reports zero warnings and zero errors, with no package or restore errors.</p><h3 id="a-release-build-does-not-start-on-another-machine" tabindex="-1">A release build does not start on another machine <a class="header-anchor" href="#a-release-build-does-not-start-on-another-machine" aria-label="Permalink to &quot;A release build does not start on another machine&quot;">​</a></h3><p><strong>Symptom.</strong> A build that compiled cleanly exits immediately on the target machine. <strong>Check.</strong> Run <code>dotnet --list-runtimes</code> there and look for <code>Microsoft.AspNetCore.App 10.x</code>; the Host uses the ASP.NET Core shared framework. <strong>Likely cause.</strong> The machine has no ASP.NET Core Runtime 10 — a framework-dependent publish does not bundle it. <strong>Fix.</strong> Install the ASP.NET Core Runtime 10 for the target platform; the publish scripts state the requirement as <code>The deployment server requires the x64 ASP.NET Core Runtime 10.0, which includes the .NET runtime.</code> <strong>Confirm recovery.</strong> Start from the release directory; the console reports <code>Server started with &lt;N&gt; active row(s).</code></p><h3 id="the-validation-toolchain-is-incomplete" tabindex="-1">The validation toolchain is incomplete <a class="header-anchor" href="#the-validation-toolchain-is-incomplete" aria-label="Permalink to &quot;The validation toolchain is incomplete&quot;">​</a></h3><p><strong>Symptom.</strong> <code>python tools/ci/serial-gates.py</code> stops before the tests, or an SDK conformance gate is reported as skipped. <strong>Check.</strong> The gate needs <code>dotnet</code>, <code>node</code>, <code>npm</code>, <code>go</code>, <code>cargo</code> and <code>rustup</code> on <code>PATH</code>, and prints <code>Missing validation toolchains: &lt;names&gt;</code> when one is absent. <strong>Likely cause.</strong> A development machine set up only for the .NET build. <strong>Fix.</strong> Install the missing toolchains and, for the Rust SDK and its WebAssembly tests, add the target named in the failure: <code>rustup target add wasm32-wasip1</code>. <strong>Confirm recovery.</strong> The rerun does not print <code>An SDK conformance gate was skipped.</code> and ends with one <code>PASS public gates:</code> or <code>PASS complete gates:</code> line.</p><h2 id="configuration-and-interpolation-problems" tabindex="-1">Configuration and interpolation problems <a class="header-anchor" href="#configuration-and-interpolation-problems" aria-label="Permalink to &quot;Configuration and interpolation problems&quot;">​</a></h2><h3 id="an-environment-variable-has-no-value" tabindex="-1">An environment variable has no value <a class="header-anchor" href="#an-environment-variable-has-no-value" aria-label="Permalink to &quot;An environment variable has no value&quot;">​</a></h3><p><strong>Symptom.</strong> <code>error: File &#39;&lt;file&gt;&#39;, row &#39;&lt;row id&gt;&#39;: environment variable &#39;&lt;NAME&gt;&#39; is not set and has no default.</code> <strong>Check.</strong> Look for <code>${NAME}</code> without a <code>:-default</code> in the profile, bundle or patch named in the error, then inspect <code>.env</code> and the process environment. A repository-root <code>.env</code> is applied to unset process variables before profile composition for every command except <code>start</code>; existing environment variables win. <strong>Likely cause.</strong> The variable is neither exported nor in <code>.env</code>, and <code>BFF_MYSQL_PASSWORD</code> has no default, so any game or management profile fails to compose without it. <strong>Fix.</strong> Set the variable for the command or add it to the git-ignored <code>.env</code>; never commit real credentials. <strong>Confirm recovery.</strong> Composition succeeds and <code>--dump-config</code> prints the effective rows.</p><h3 id="the-mysql-password-is-empty" tabindex="-1">The MySQL password is empty <a class="header-anchor" href="#the-mysql-password-is-empty" aria-label="Permalink to &quot;The MySQL password is empty&quot;">​</a></h3><p><strong>Symptom.</strong> <code>error: Activation of row &#39;persistence.mysql&#39; (plugin &#39;persistence.mysql&#39;) failed: Invalid configuration for row &#39;persistence.mysql&#39;: connection_string is missing Password (BFF_MYSQL_PASSWORD is required and must not be empty).</code> <strong>Check.</strong> A copied <code>.env.example</code> contains <code>BFF_MYSQL_PASSWORD=</code>, so interpolation succeeds with an empty string and the failure appears only when the row activates. <strong>Likely cause.</strong> An empty placeholder left in <code>.env</code>. <strong>Fix.</strong> Set a disposable nonempty value for local checks and add the isolated patch so no database is contacted; use real credentials only for a deliberate persistent deployment. <strong>Confirm recovery.</strong> With the isolated patch, <code>persistence.memory</code> activates and the log reports in-memory persistence active.</p><h3 id="a-profile-patch-or-option-name-is-wrong" tabindex="-1">A profile, patch or option name is wrong <a class="header-anchor" href="#a-profile-patch-or-option-name-is-wrong" aria-label="Permalink to &quot;A profile, patch or option name is wrong&quot;">​</a></h3><p><strong>Symptom.</strong> One of <code>error: Profile &#39;&lt;id&gt;&#39; not found: expected &#39;&lt;path&gt;&#39;.</code>, <code>error: Patch file &#39;&lt;path&gt;&#39; does not exist.</code>, <code>error: Unknown option &#39;&lt;option&gt;&#39;.</code>, <code>error: Unknown command &#39;&lt;command&gt;&#39;.</code>, <code>error: Option &#39;&lt;option&gt;&#39; requires a value.</code> <strong>Check.</strong> Run <code>bff profiles list</code> and <code>bff --help</code>; profile ids are directory names under <code>profiles/</code>, and the help text lists the accepted options. <strong>Likely cause.</strong> A typo, a profile that does not exist, or an option placed after a command that does not take it. <strong>Fix.</strong> Correct the id or option; for a local run keep <code>--patch tools/local-checks/isolated-memory.patch.yaml</code>. <strong>Confirm recovery.</strong> <code>bff profiles list</code> prints the profile with its description and the corrected command composes.</p><h3 id="a-configuration-key-is-unknown-or-invalid" tabindex="-1">A configuration key is unknown or invalid <a class="header-anchor" href="#a-configuration-key-is-unknown-or-invalid" aria-label="Permalink to &quot;A configuration key is unknown or invalid&quot;">​</a></h3><p><strong>Symptom.</strong> <code>error: Invalid configuration for row &#39;&lt;row id&gt;&#39;: unknown key &#39;&lt;key&gt;&#39;</code>, or a conversion or validation failure for the same row. <strong>Check.</strong> Plugin options are snake_case YAML keys mapped to PascalCase properties; the plugin&#39;s option class lists what it accepts. Check the row id in the message and the <code>plugin</code> field it maps to. <strong>Likely cause.</strong> A misspelled key, a key from an older guide, or a value of the wrong type or range. <strong>Fix.</strong> Correct the key or value; every failure for the row is listed in one message, so fix all of them. <strong>Confirm recovery.</strong> <code>--dump-config</code> succeeds and shows the corrected value.</p><h3 id="the-effective-configuration-is-not-what-you-expected" tabindex="-1">The effective configuration is not what you expected <a class="header-anchor" href="#the-effective-configuration-is-not-what-you-expected" aria-label="Permalink to &quot;The effective configuration is not what you expected&quot;">​</a></h3><p><strong>Symptom.</strong> The server behaves as if a row were enabled, or a port different from the one you edited, were in use. <strong>Check.</strong> Layers apply in order: bundles, profile patches, then CLI patches. Print the result without starting the host:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/BubbleFighter.Fantasy.Host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kr-812</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --patch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/local-checks/isolated-memory.patch.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dump-config</span></span></code></pre></div><p><strong>Likely cause.</strong> A later layer replaced the row or its <code>disabled</code> flag; the isolated patch is the last layer and enables in-memory persistence. <strong>Fix.</strong> Change the layer that should own the value; do not add the same override to two layers. <strong>Confirm recovery.</strong> The dump shows the expected flags and values. It can contain interpolated secrets such as the MySQL connection string — redact it before sharing.</p><h2 id="startup-activation-and-plugin-states" tabindex="-1">Startup, activation and plugin states <a class="header-anchor" href="#startup-activation-and-plugin-states" aria-label="Permalink to &quot;Startup, activation and plugin states&quot;">​</a></h2><p>Every row publishes a state after a start attempt. Read it from the console log or the admin API:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-RestMethod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> http:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">127.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8080</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">plugins </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Select-Object</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rowId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> plugin</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> state</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> error</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/api/plugins</span></span></code></pre></div><p><code>/api/plugins</code> returns one object per runtime instance with <code>rowId</code>, <code>plugin</code>, <code>source</code>, <code>state</code>, <code>error</code>, <code>codeRefreshPolicy</code>, <code>codeLifetime</code>, <code>restartRequiredForReclamation</code>, <code>isRetiring</code>, <code>overrides</code>, <code>version</code>, <code>contractVersions</code> and <code>supportedBuilds</code>. Only <code>Active</code> is a healthy running state.</p><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th><th>What to do</th></tr></thead><tbody><tr><td><code>Active</code></td><td>Activated; effects are live</td><td>none</td></tr><tr><td><code>Pending</code></td><td>Desired, but services, providers or a definition source are missing</td><td>read <code>error</code>, fix the dependency</td></tr><tr><td><code>Failed</code></td><td>Activation or owned work failed</td><td>read <code>error</code>, fix the cause, reload or restart</td></tr><tr><td><code>Unloading</code></td><td>Effects closed, teardown running</td><td>wait; do not start the row again</td></tr><tr><td><code>Unloaded</code></td><td>Disabled or unloaded, no live effects</td><td>expected for disabled rows</td></tr><tr><td><code>CleanupIncomplete</code></td><td>Teardown still running past its limit or cancelled</td><td>ownership retained; investigate before retrying</td></tr><tr><td><code>CleanupFailed</code></td><td>Teardown reported an error</td><td>resources cannot be assumed released; restart is refused</td></tr><tr><td><code>WorkFailed</code></td><td>Owned background work failed</td><td>resources stay owned until teardown settles</td></tr></tbody></table><h3 id="server-startup-did-not-converge" tabindex="-1">Server startup did not converge <a class="header-anchor" href="#server-startup-did-not-converge" aria-label="Permalink to &quot;Server startup did not converge&quot;">​</a></h3><p><strong>Symptom.</strong> The process exits with code 1 and <code>error: Server startup did not converge (WaitingForDependencies): &lt;row id&gt;: Pending (&lt;diagnostic&gt;); &lt;row id&gt;: Failed (&lt;diagnostic&gt;).</code>; the console also logs <code>Lifecycle revision &lt;N&gt; for &#39;&lt;row id&gt;&#39; did not converge.</code> <strong>Check.</strong> Read every listed row, then compare <code>/api/plugins</code> with the <code>--dump-config</code> dump. <strong>Likely cause.</strong> At least one non-disabled row did not reach <code>Active</code>: a missing provider, missing client data, a wrong port, or a value that fails binding. <strong>Fix.</strong> Fix the first listed row, not the last; if a row is disabled on purpose, confirm the effective dump disables it. <strong>Confirm recovery.</strong> The console reports <code>Server started with &lt;N&gt; active row(s).</code> and <code>GET /health</code> answers <code>{&quot;status&quot;:&quot;ok&quot;, ...}</code>.</p><h3 id="a-row-stays-pending" tabindex="-1">A row stays Pending <a class="header-anchor" href="#a-row-stays-pending" aria-label="Permalink to &quot;A row stays Pending&quot;">​</a></h3><p><strong>Symptom.</strong> The row never activates and <code>error</code> explains why, usually <code>Waiting for services: &lt;service types&gt;; provider rows: &lt;rows&gt;; override rows: &lt;rows&gt;.</code> or <code>Definition source for plugin &#39;&lt;plugin&gt;&#39; is unavailable.</code> <strong>Check.</strong> Find the provider or definition source named in the message and check its row state. <strong>Likely cause.</strong> A required service, optional provider or handler-override target is disabled, failed or absent from the profile; or an SDK loader row that publishes the plugin has not activated. <strong>Fix.</strong> Enable or fix the named provider row, or remove the consumer if the capability is not wanted. <strong>Confirm recovery.</strong> The row becomes <code>Active</code> after a reload or restart, and startup converges.</p><h3 id="a-row-is-failed" tabindex="-1">A row is Failed <a class="header-anchor" href="#a-row-is-failed" aria-label="Permalink to &quot;A row is Failed&quot;">​</a></h3><p><strong>Symptom.</strong> <code>error: Activation of row &#39;&lt;row id&gt;&#39; (plugin &#39;&lt;plugin&gt;&#39;) failed: &lt;cause&gt;.</code> <strong>Check.</strong> Read the <code>error</code> field and the full cause in the console log; the wrapper names the row and plugin, and the inner message names the actual problem — client data, MySQL, SQLite, a port, an unknown key or an unknown plugin. <strong>Likely cause.</strong> Anything the plugin validates during activation. <strong>Fix.</strong> Fix the inner cause. A row with <code>Automatic activation attempt limit &lt;N&gt; reached for row &#39;&lt;row id&gt;&#39;.</code> stops retrying automatically and needs an explicit reload once the cause is fixed. <strong>Confirm recovery.</strong> The row becomes <code>Active</code>.</p><h3 id="cleanupincomplete-or-cleanupfailed" tabindex="-1">CleanupIncomplete or CleanupFailed <a class="header-anchor" href="#cleanupincomplete-or-cleanupfailed" aria-label="Permalink to &quot;CleanupIncomplete or CleanupFailed&quot;">​</a></h3><p><strong>Symptom.</strong> A row that was unloading shows <code>CleanupIncomplete</code> or <code>CleanupFailed</code> in <code>/api/plugins</code>, and its <code>error</code> field and the console log carry the teardown failure. The unload or reload call that triggered teardown can also fail with <code>Row &#39;&lt;row id&gt;&#39; teardown is &lt;state&gt;; ownership and dependencies are retained.</code>, where <code>&lt;state&gt;</code> is the state the row reached. <strong>Check.</strong> Read the row&#39;s <code>error</code> and the console log; <code>CleanupIncomplete</code> means teardown is still running past its limit or the caller went away, while <code>CleanupFailed</code> means an owned disposer threw. <strong>Likely cause.</strong> A resource that blocks on release, an owned background task that does not finish, or a failing disposer. <strong>Fix.</strong> Do not force the row to restart: a restart is refused while ownership remains (<code>Activation is refused while failed work or cleanup ownership remains: &lt;row ids&gt;.</code>). Let cleanup settle or stop the server; if it cannot settle, restart the process and fix the plugin. <strong>Confirm recovery.</strong> The state becomes <code>Unloaded</code> and the server shuts down cleanly.</p><h3 id="a-plugin-is-unknown-or-a-row-id-is-duplicated" tabindex="-1">A plugin is unknown or a row id is duplicated <a class="header-anchor" href="#a-plugin-is-unknown-or-a-row-id-is-duplicated" aria-label="Permalink to &quot;A plugin is unknown or a row id is duplicated&quot;">​</a></h3><p><strong>Symptom.</strong> <code>error: Row &#39;&lt;row id&gt;&#39; references unknown plugin &#39;&lt;plugin&gt;&#39;.</code> or <code>error: Duplicate row id &#39;&lt;row id&gt;&#39; in profile &#39;&lt;profile id&gt;&#39;.</code> <strong>Check.</strong> Run <code>bff plugins list</code> and look for the plugin id; check that its assembly is under the plugin root (<code>plugins/</code> next to the host, or a directory passed with <code>--plugin-root</code>). For a duplicate, find the bundle or patch that contributes the second row. <strong>Likely cause.</strong> A stale or missing plugin build, a plugin directory not copied, a typo in the <code>plugin</code> field, or a patch reinserting an existing id. <strong>Fix.</strong> Rebuild the solution (the Host build replaces its <code>plugins</code> directory from <code>artifacts/plugins</code>), use <code>--no-incremental</code> if a stale copy is suspected, and remove or rename the duplicate row. <strong>Confirm recovery.</strong> <code>bff plugins list</code> prints the id, version, supported builds and origin, and <code>--dump-config</code> lists the row once.</p><h3 id="a-required-service-is-missing-at-activation" tabindex="-1">A required service is missing at activation <a class="header-anchor" href="#a-required-service-is-missing-at-activation" aria-label="Permalink to &quot;A required service is missing at activation&quot;">​</a></h3><p><strong>Symptom.</strong> A failed row reports <code>Row &#39;&lt;row id&gt;&#39; cannot &lt;verb&gt;; missing service(s): &lt;service types&gt;.</code> <strong>Check.</strong> Identify the row that should publish the service; the dependency is the declared interface, not a row id. <strong>Likely cause.</strong> The provider row is disabled, failed or absent, or it lives in a separate service realm through <code>isolated_services</code>. <strong>Fix.</strong> Enable the provider or remove the service from the consumer&#39;s declaration; check <code>parent_id</code> and <code>isolated_services</code> when provider and consumer should live in different trees. <strong>Confirm recovery.</strong> The provider is <code>Active</code> first, then the consumer activates on the next reconciliation.</p><h2 id="ports-bind-addresses-nat-and-admin-authentication" tabindex="-1">Ports, bind addresses, NAT and admin authentication <a class="header-anchor" href="#ports-bind-addresses-nat-and-admin-authentication" aria-label="Permalink to &quot;Ports, bind addresses, NAT and admin authentication&quot;">​</a></h2><h3 id="a-port-is-already-in-use" tabindex="-1">A port is already in use <a class="header-anchor" href="#a-port-is-already-in-use" aria-label="Permalink to &quot;A port is already in use&quot;">​</a></h3><p><strong>Symptom.</strong> A listener row fails with <code>error: Activation of row &#39;game-listener&#39; (plugin &#39;net.tcp&#39;) failed: &lt;operating system socket error&gt;</code>. <strong>Check.</strong> Find the owner before changing anything: <code>Get-NetTCPConnection -LocalPort 7110 -State Listen | Select-Object LocalAddress, LocalPort, OwningProcess</code> then <code>Get-Process -Id &lt;owningProcess&gt;</code> on Windows, or <code>sudo ss -ltnp | grep :7110</code> on Linux. <strong>Likely cause.</strong> Another server instance, the same profile in a second terminal, or an unrelated process. <strong>Fix.</strong> Stop only the process you identified, or move this profile&#39;s port with its variable, for example <code>KR_812_GAME_PORT</code>. Do not kill every .NET process on the machine. <strong>Confirm recovery.</strong> The log shows <code>Row &#39;game-listener&#39; listening on &lt;address&gt; (protocol &lt;profile&gt;/game).</code> and the port is listening.</p><h3 id="clients-cannot-connect-through-nat-or-a-firewall" tabindex="-1">Clients cannot connect through NAT or a firewall <a class="header-anchor" href="#clients-cannot-connect-through-nat-or-a-firewall" aria-label="Permalink to &quot;Clients cannot connect through NAT or a firewall&quot;">​</a></h3><p><strong>Symptom.</strong> The server listens, but a client on another machine cannot connect. <strong>Check.</strong> Listeners bind <code>${BFF_BIND_HOST:-0.0.0.0}</code>, while the client is told <code>${BFF_PUBLIC_HOST:-127.0.0.1}</code> in the center gate address and the relay advertisement. The public default is loopback, which works only on the same machine. Check both values in <code>--dump-config</code>, then test the path with <code>Test-NetConnection &lt;public-host&gt; -Port 7110</code> on Windows or <code>nc -vz &lt;public-host&gt; 7110</code> on Linux. <strong>Likely cause.</strong> <code>BFF_PUBLIC_HOST</code> left at its default, a firewall blocking the port, or a port-forward that does not match the advertised port. <strong>Fix.</strong> Set <code>BFF_BIND_HOST</code> and <code>BFF_PUBLIC_HOST</code> to addresses the client can reach, open only the ports the chosen profile needs, and forward the advertised numbers. <strong>Confirm recovery.</strong> The client reaches the login or center connection and <code>/api/sessions</code> shows it while connected.</p><h3 id="the-relay-connection-fails" tabindex="-1">The relay connection fails <a class="header-anchor" href="#the-relay-connection-fails" aria-label="Permalink to &quot;The relay connection fails&quot;">​</a></h3><p><strong>Symptom.</strong> Login works on a modern build, but the match connection does not, or the relay port never listens. <strong>Check.</strong> The <code>kr-1256</code> profile has <code>${KR_1256_GAME_PORT:-7100}</code> and <code>${KR_1256_RELAY_PORT:-7101}</code> listeners, and advertises <code>relay_advertise_ipv4</code> and <code>relay_advertise_port</code> (default <code>${KR_1256_RELAY_PUBLIC_PORT:-7101}</code>). Compare the listener with the advertisement. <strong>Likely cause.</strong> Advertised and listening ports differ behind NAT, a patch disabled the relay row, or the client is a legacy build. <strong>Fix.</strong> Make the advertised relay address and port reachable and keep both relay values consistent. Legacy builds have no relay listener yet (<code>No relay listener on the legacy builds yet.</code> in the legacy bundle), so do not expect a relay connection there. <strong>Confirm recovery.</strong> The relay port listens and the match connection appears in <code>/api/sessions</code> with <code>matchBound</code> set.</p><h3 id="the-admin-api-or-webui-is-unreachable-or-unauthorized" tabindex="-1">The admin API or WebUI is unreachable or unauthorized <a class="header-anchor" href="#the-admin-api-or-webui-is-unreachable-or-unauthorized" aria-label="Permalink to &quot;The admin API or WebUI is unreachable or unauthorized&quot;">​</a></h3><p><strong>Symptom.</strong> The browser cannot reach the WebUI, or <code>/api/...</code> answers 401 with <code>{&quot;error&quot;:&quot;unauthorized&quot;}</code>. <strong>Check.</strong> The admin row binds <code>${BFF_ADMIN_HOST:-127.0.0.1}:${BFF_ADMIN_PORT:-8080}</code>, loopback by default. When <code>BFF_ADMIN_TOKEN</code> is set, every <code>/api</code> request needs the exact header <code>Authorization: Bearer &lt;token&gt;</code>; <code>/health</code> and the WebUI files stay open. During first-run setup, <code>/api/plugins</code> answers 401 until an administrator account exists — that is the authentication model, not a server failure; <code>/health</code> and <code>/api/setup/status</code> stay reachable. <strong>Likely cause.</strong> The listener is on loopback and the browser is elsewhere, the token is missing or different, or a non-loopback installation listener was configured without a bootstrap token. <strong>Fix.</strong> Set <code>BFF_ADMIN_HOST</code> to the interface you need, keep <code>BFF_ADMIN_TOKEN</code> nonempty, and set <code>bootstrap_token</code> (<code>BFF_SETUP_TOKEN</code>) to at least 32 characters for a non-loopback installation listener. The row otherwise fails with <code>A non-loopback installation listener requires an explicit bootstrap_token of at least 32 characters.</code> <strong>Confirm recovery.</strong> <code>/health</code> returns <code>{&quot;status&quot;:&quot;ok&quot;, ...}</code> and an authenticated <code>/api/plugins</code> call returns the instance list.</p><h2 id="persistence-and-migrations" tabindex="-1">Persistence and migrations <a class="header-anchor" href="#persistence-and-migrations" aria-label="Permalink to &quot;Persistence and migrations&quot;">​</a></h2><h3 id="mysql-connection-or-authentication-fails" tabindex="-1">MySQL connection or authentication fails <a class="header-anchor" href="#mysql-connection-or-authentication-fails" aria-label="Permalink to &quot;MySQL connection or authentication fails&quot;">​</a></h3><p><strong>Symptom.</strong> <code>error: Activation of row &#39;persistence.mysql&#39; (plugin &#39;persistence.mysql&#39;) failed: Failed to open MySQL at &lt;host&gt;:&lt;port&gt; database &#39;&lt;database&gt;&#39; as &#39;&lt;user&gt;&#39;.</code> <strong>Check.</strong> Check <code>BFF_MYSQL_HOST</code>, <code>BFF_MYSQL_PORT</code>, <code>BFF_MYSQL_USER</code>, <code>BFF_MYSQL_PASSWORD</code> and <code>BFF_MYSQL_DATABASE</code>, and that the server is reachable. The database name must be <code>bf_game_db</code>; anything else fails binding with <code>connection_string Database must be &#39;bf_game_db&#39; (BFF_MYSQL_DATABASE); got &#39;&lt;database&gt;&#39;.</code> <strong>Likely cause.</strong> Wrong host, port, user or password, no reachable server, or a refused database name. <strong>Fix.</strong> Correct the variables for a deliberate persistent deployment; never point a local check at a production database. <strong>Confirm recovery.</strong> The log reports <code>MySQL persistence connected to &lt;host&gt;:&lt;port&gt;/&lt;database&gt; as &lt;user&gt;.</code></p><h3 id="migrations-fail" tabindex="-1">Migrations fail <a class="header-anchor" href="#migrations-fail" aria-label="Permalink to &quot;Migrations fail&quot;">​</a></h3><p><strong>Symptom.</strong> Activation fails while reading or applying embedded migrations, with one of <code>Embedded SQL resource &#39;&lt;resource&gt;&#39; is not named NNNN_description.sql.</code>, <code>Duplicate embedded migration version &lt;version&gt;.</code>, <code>No embedded SQL migrations were found.</code> or <code>Embedded migration &#39;&lt;resource&gt;&#39; is empty.</code> <strong>Check.</strong> Migrations are embedded resources applied in filename order when the plugin activates with <code>auto_migrate: true</code>. <strong>Likely cause.</strong> A damaged plugin build, or a migration resource that was renamed or emptied. <strong>Fix.</strong> Do not edit a live <code>schema_migrations</code> table by hand; rebuild the plugin from a clean checkout. There is no downgrade migration path, so restore the backup taken before the schema changed if you must return to an older build. <strong>Confirm recovery.</strong> Activation logs one <code>Applied migration &lt;version&gt; (&lt;name&gt;).</code> line per pending migration, then the connection line.</p><h3 id="two-persistence-providers-are-enabled" tabindex="-1">Two persistence providers are enabled <a class="header-anchor" href="#two-persistence-providers-are-enabled" aria-label="Permalink to &quot;Two persistence providers are enabled&quot;">​</a></h3><p><strong>Symptom.</strong> A persistence row fails with <code>Service &#39;&lt;contract&gt;&#39; is already registered in realm &lt;id&gt;.</code> <strong>Check.</strong> Only one of <code>persistence.memory</code>, <code>persistence.sqlite</code> and <code>persistence.mysql</code> may be enabled. Check the <code>disabled</code> flags in <code>--dump-config</code>; the isolated patch enables memory and disables MySQL but leaves SQLite disabled. <strong>Likely cause.</strong> A patch enabled a second provider without disabling the first. <strong>Fix.</strong> Disable the providers you do not use in the same patch. <strong>Confirm recovery.</strong> Exactly one persistence provider is <code>Active</code> and the others are <code>Unloaded</code>.</p><h3 id="sqlite-path-or-locking-problems" tabindex="-1">SQLite path or locking problems <a class="header-anchor" href="#sqlite-path-or-locking-problems" aria-label="Permalink to &quot;SQLite path or locking problems&quot;">​</a></h3><p><strong>Symptom.</strong> The SQLite row fails to activate, or writes fail with <code>SQLite transaction committed but WAL truncation failed; further operations are refused.</code> <strong>Check.</strong> <code>database_path</code> must be an absolute file path with a file name; a relative path fails with <code>database_path must be an absolute file path.</code> Keep the save outside release and log directories, and run one server per save. The lock wait is <code>busy_timeout_ms</code>, default 5000. <strong>Likely cause.</strong> A relative path, a read-only directory, or two processes opening the same save. <strong>Fix.</strong> Fix the path and permissions and stop the second process. <strong>Confirm recovery.</strong> The log reports <code>SQLite save active; capacity &lt;players&gt; players, &lt;accounts&gt; accounts, &lt;bytes&gt; main-file bytes.</code></p><h3 id="data-is-empty-after-a-restart" tabindex="-1">Data is empty after a restart <a class="header-anchor" href="#data-is-empty-after-a-restart" aria-label="Permalink to &quot;Data is empty after a restart&quot;">​</a></h3><p><strong>Symptom.</strong> Accounts, items or progress disappear after stopping and starting the server. <strong>Check.</strong> <code>--dump-config</code> shows which persistence row is enabled. With the isolated patch, or any configuration that enables <code>persistence.memory</code>, state is process-local; the activation log says <code>In-memory persistence active for up to &lt;players&gt; players and &lt;movement actors&gt; movement actor(s); state is process-local and resets on restart.</code> <strong>Likely cause.</strong> In-memory persistence was expected to be durable. <strong>Fix.</strong> For durable state, enable <code>persistence.sqlite</code> or <code>persistence.mysql</code> and disable the other providers; for local experiments keep the isolated patch and expect the reset. <strong>Confirm recovery.</strong> After a restart with a durable provider, the same account can log in.</p><h3 id="restore-a-backup" tabindex="-1">Restore a backup <a class="header-anchor" href="#restore-a-backup" aria-label="Permalink to &quot;Restore a backup&quot;">​</a></h3><p><strong>Symptom.</strong> A database change needs to be undone. <strong>Check.</strong> The server has no command that restores a database; restoring is a database-level operation, and the server must be stopped before touching the database. <strong>Likely cause.</strong> A bad migration, an accidental write or a failed upgrade. <strong>Fix.</strong> Restore the backup taken before the change, then start the server with the configuration that matches the restored schema. Do not edit <code>schema_migrations</code> or delete rows to fake a rollback. <strong>Confirm recovery.</strong> <code>/health</code> is fine, the persistence row is <code>Active</code>, and the expected accounts and data are present.</p><h2 id="client-data" tabindex="-1">Client data <a class="header-anchor" href="#client-data" aria-label="Permalink to &quot;Client data&quot;">​</a></h2><h3 id="the-clientdata-row-fails-activation" tabindex="-1">The clientdata row fails activation <a class="header-anchor" href="#the-clientdata-row-fails-activation" aria-label="Permalink to &quot;The clientdata row fails activation&quot;">​</a></h3><p><strong>Symptom.</strong> <code>error: Activation of row &#39;clientdata&#39; (plugin &#39;clientdata&#39;) failed: clientdata: neither data_directory &#39;&lt;base&gt;/client-data/&lt;profile&gt;/data&#39; nor raw_directory &#39;&lt;base&gt;/client-data/&lt;profile&gt;/dataraw&#39; exists. Provision the configured client-data directories before enabling this row.</code> <strong>Check.</strong> Game profiles resolve <code>${BFF_CLIENT_DATA:-client-data}/${BFF_PROFILE_ID}/data</code> and <code>.../dataraw</code>, relative to the working directory. Compare both paths in the error with the files on disk and with <code>BFF_CLIENT_DATA</code> in <code>--dump-config</code>. <strong>Likely cause.</strong> The client data was never supplied for this build, <code>BFF_CLIENT_DATA</code> points elsewhere, or the server was started from a different directory. <strong>Fix.</strong> Supply the matching local client data, set <code>BFF_CLIENT_DATA</code> to its root, or use the <code>management</code> profile when you only need administration and storage. The repository does not include the client or its proprietary data. <strong>Confirm recovery.</strong> The <code>clientdata</code> row becomes <code>Active</code> and a game profile starts with <code>Server started with &lt;N&gt; active row(s).</code></p><h3 id="a-client-file-is-missing-or-the-version-does-not-match" tabindex="-1">A client file is missing or the version does not match <a class="header-anchor" href="#a-client-file-is-missing-or-the-version-does-not-match" aria-label="Permalink to &quot;A client file is missing or the version does not match&quot;">​</a></h3><p><strong>Symptom.</strong> A feature fails with <code>clientdata: no client file &#39;&lt;path&gt;&#39; in the archives or the loose files.</code>, or <code>/api/logs</code> records <code>Session &lt;id&gt; reported client version &lt;reported&gt;, expected &lt;expected&gt;.</code> <strong>Check.</strong> For a missing file, confirm the relative path in <code>data/</code> or a loose file in <code>dataraw/</code> with the client&#39;s own spelling; loose files win over archives. For a version mismatch, compare the client&#39;s <code>ClientVersion_Major</code> with the profile&#39;s <code>client_build</code> and profile id. <strong>Likely cause.</strong> An incomplete client-data copy, an archive that was not copied, or a client build that does not match the selected profile. <strong>Fix.</strong> Copy the complete data for this build, and start the profile that matches the client build; do not edit a profile to accept a build the code does not support. <strong>Confirm recovery.</strong> The feature reads the file, and the session connects without the mismatch warning.</p><h3 id="a-setup-client-data-import-fails" tabindex="-1">A setup client-data import fails <a class="header-anchor" href="#a-setup-client-data-import-fails" aria-label="Permalink to &quot;A setup client-data import fails&quot;">​</a></h3><p><strong>Symptom.</strong> The setup assistant reports a failed import, or the API answers 400, 413 or 409 with <code>{&quot;error&quot;:&quot;client_data_invalid&quot;}</code>, <code>{&quot;error&quot;:&quot;client_data_limit&quot;}</code> or <code>{&quot;error&quot;:&quot;client_data_busy&quot;}</code>. <strong>Check.</strong> The import accepts a prepared folder or a classic ZIP. The defaults bound one copy at 8 GiB uploaded, 16 GiB extracted, 32,768 files or ZIP entries, 64 retained copies, 64 GiB of retained storage and 20 minutes. ZIP64 and split archives are not supported; <code>client_data_busy</code> means another import is already running. <strong>Likely cause.</strong> Too many or too large files, a layout the importer does not recognize, or a second concurrent import. <strong>Fix.</strong> Import a prepared <code>&lt;build&gt;/data</code> and <code>&lt;build&gt;/dataraw</code> layout within the limits, adjust the limits on the <code>installation</code> row within their allowed ranges when the deployment needs it, and wait for a running import to finish before retrying. <strong>Confirm recovery.</strong> The import returns a root path and the <code>clientdata</code> row for the matching profile activates.</p><h2 id="sdk-plugin-problems" tabindex="-1">SDK plugin problems <a class="header-anchor" href="#sdk-plugin-problems" aria-label="Permalink to &quot;SDK plugin problems&quot;">​</a></h2><h3 id="the-sdk-plugin-process-does-not-start" tabindex="-1">The SDK plugin process does not start <a class="header-anchor" href="#the-sdk-plugin-process-does-not-start" aria-label="Permalink to &quot;The SDK plugin process does not start&quot;">​</a></h3><p><strong>Symptom.</strong> <code>error: Activation of row &#39;&lt;row id&gt;&#39; (plugin &#39;loader.process&#39;) failed: SDK plugin process &#39;&lt;command&gt;&#39; could not start in &#39;&lt;directory&gt;&#39;: &lt;reason&gt;</code> or <code>SDK plugin process &#39;&lt;command&gt;&#39; did not start.</code> <strong>Check.</strong> Check the loader row&#39;s <code>plugins[].command</code>, <code>args</code>, <code>cwd</code> and <code>env</code>; a command with a directory part resolves against <code>base_dir</code>, the rest is looked up on <code>PATH</code>, and a missing <code>cwd</code> fails configuration with <code>plugins[&lt;n&gt;].cwd: directory &#39;&lt;path&gt;&#39; does not exist</code>. <strong>Likely cause.</strong> The interpreter or executable is not installed, the working directory is wrong, or <code>PATH</code> does not contain the command. <strong>Fix.</strong> Install the runtime, correct <code>command</code>/<code>cwd</code>, or pass an absolute path. <strong>Confirm recovery.</strong> The row activates and the plugin id appears in <code>/api/plugins</code> with <code>state</code> <code>Active</code>.</p><h3 id="the-plugin-writes-to-stdout" tabindex="-1">The plugin writes to stdout <a class="header-anchor" href="#the-plugin-writes-to-stdout" aria-label="Permalink to &quot;The plugin writes to stdout&quot;">​</a></h3><p><strong>Symptom.</strong> <code>error: Activation of row &#39;&lt;row id&gt;&#39; (plugin &#39;loader.process&#39;) failed: SDK plugin process broke the protocol: stdout carried a line that is not JSON (&lt;detail&gt;); stdout is reserved for the protocol, use stderr for diagnostics.</code> <strong>Check.</strong> Find the print, banner or progress output that writes to stdout. <strong>Likely cause.</strong> A debug print, a library banner or a progress bar on stdout. <strong>Fix.</strong> Send every diagnostic to stderr; keep stdout for JSON-RPC lines only. <strong>Confirm recovery.</strong> The plugin handshakes and activates.</p><h3 id="protocol-or-capability-mismatch" tabindex="-1">Protocol or capability mismatch <a class="header-anchor" href="#protocol-or-capability-mismatch" aria-label="Permalink to &quot;Protocol or capability mismatch&quot;">​</a></h3><p><strong>Symptom.</strong> A declaration or negotiation failure such as <code>SDK plugin source &#39;&lt;source&gt;&#39; answered initialize without a supported protocol_version (1 or 2).</code>, <code>protocol v1 allows only IMessageRouter in requires and optional.</code> or <code>requires_many and optional_many require protocol v2.</code> <strong>Check.</strong> Compare the plugin manifest with the host&#39;s supported protocol versions and with the declarations each version allows; typed messages, events, providers and decorators need protocol v2. <strong>Likely cause.</strong> An old SDK or manifest pinned to protocol v1 while using v2 declarations. <strong>Fix.</strong> Update the SDK or manifest, or restrict the declaration to what v1 supports. <strong>Confirm recovery.</strong> The source publishes its definitions and the dependent rows activate.</p><h3 id="a-call-times-out-or-is-refused" tabindex="-1">A call times out or is refused <a class="header-anchor" href="#a-call-times-out-or-is-refused" aria-label="Permalink to &quot;A call times out or is refused&quot;">​</a></h3><p><strong>Symptom.</strong> <code>SDK plugin &lt;label&gt; did not answer &#39;&lt;method&gt;&#39; within &lt;n&gt; ms (request_timeout_ms).</code> or <code>SDK plugin &lt;label&gt; already has &lt;n&gt; requests in flight (max_in_flight &lt;n&gt;).</code> <strong>Check.</strong> Check the loader row&#39;s <code>request_timeout_ms</code> and <code>max_in_flight</code>, and measure what the plugin does in the call; a blocked event loop shows up here. <strong>Likely cause.</strong> A slow or blocked handler, or a burst above the in-flight bound. <strong>Fix.</strong> Make the handler return promptly, raise the bounds only with a measured reason, and retry only idempotent operations — a timeout does not undo a change the plugin already committed. <strong>Confirm recovery.</strong> Calls complete within the configured timeout and the in-flight count stays below the bound.</p><h3 id="a-webassembly-module-fails-to-load" tabindex="-1">A WebAssembly module fails to load <a class="header-anchor" href="#a-webassembly-module-fails-to-load" aria-label="Permalink to &quot;A WebAssembly module fails to load&quot;">​</a></h3><p><strong>Symptom.</strong> <code>error: Activation of row &#39;&lt;row id&gt;&#39; (plugin &#39;loader.wasm&#39;) failed: WebAssembly plugin &#39;&lt;module&gt;&#39; exports no &#39;_start&#39;; build it as a WASI command (wasm32-wasip1 or GOOS=wasip1).</code> or <code>WebAssembly plugin &#39;&lt;module&gt;&#39; could not be loaded: &lt;reason&gt;</code>. <strong>Check.</strong> Check <code>plugins[].module</code> in the <code>loader.wasm</code> row and the module&#39;s build target. <strong>Likely cause.</strong> A module built for the wrong target, or a path that does not exist. <strong>Fix.</strong> Build a WASI command module with the Rust SDK (<code>wasm32-wasip1</code>) or the Go SDK (<code>GOOS=wasip1</code>), then correct the module path. <strong>Confirm recovery.</strong> The module is accepted and its definitions activate.</p><h2 id="reporting-a-problem" tabindex="-1">Reporting a problem <a class="header-anchor" href="#reporting-a-problem" aria-label="Permalink to &quot;Reporting a problem&quot;">​</a></h2><p>Include enough for another person to reproduce the failure. Use this template, one report per problem:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Source revision: &lt;git rev-parse --short HEAD, or release/package version&gt;</span></span>\n<span class="line"><span>Operating system: &lt;Windows 11 x64 / Debian 13 x64 / container image&gt;</span></span>\n<span class="line"><span>Profile: &lt;profile id or the matching bff profiles list line&gt;</span></span>\n<span class="line"><span>Command: &lt;exact command; include --patch tools/local-checks/isolated-memory.patch.yaml for local checks&gt;</span></span>\n<span class="line"><span>Expected: &lt;what should have happened&gt;</span></span>\n<span class="line"><span>Actual: &lt;what happened, with exit code&gt;</span></span>\n<span class="line"><span>First error: &lt;the first error: line&gt;</span></span>\n<span class="line"><span>Affected rows: &lt;rowId, state and error from /api/plugins&gt;</span></span>\n<span class="line"><span>Evidence: &lt;console excerpt, TRX result, dump path&gt;</span></span>\n<span class="line"><span>Source of the observation: &lt;real game client, automated test, or both&gt;</span></span></code></pre></div><p>Before attaching anything, remove tokens, passwords, account names, player identities, public addresses and packet payloads that contain personal data. Do not attach client data, proprietary files or private investigation material. Redact <code>--dump-config</code> output, which can contain interpolated credentials.</p><p>State clearly whether the problem was seen with a real game client or only in automated checks; an automated pass or failure does not establish client compatibility.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="./configuration">Configuration</a> for profiles, patches, environment variables, ports and persistence.</li><li><a href="./deployment">Deployment</a> for running the server for other people, upgrades and rollback.</li><li><a href="./plugins">Plugins</a> and <a href="./sdk-protocol">SDK protocol</a> for activation and lifecycle details.</li><li><a href="./launcher">Launcher</a> for launcher accounts, session tickets, launcher API version gates and the companion launcher&#39;s own errors.</li></ul>',95)])])}const u=t(n,[["render",i]]);export{g as __pageData,u as default};
